//! gracefully (no panic) on garbage or an unknown version.

use crate::eventlog::event::ConversationId;
use crate::file::crypto::{
    FileError, FileKey, chunk_hash, file_checksum, open_chunk, open_chunk_indexed,
};
use bincode::Options;
